const $=id=>document.getElementById(id),ids=['memoryType','unifiedTotal','modelBudget','vram','params','quant','context','offload','headroom','layers','heads','dim','cache','overhead'];
let selectedModel='';let mode='gpu';const defaults=Object.fromEntries(ids.map(id=>[id,$(id).value]));
function state(){const s=Object.fromEntries(ids.map(id=>[id,['quant','memoryType'].includes(id)?$(id).value:Number($(id).value)]));s.dedicatedVram=s.vram;s.dedicatedHeadroom=s.headroom;if(s.memoryType==='unified'){s.vram=s.modelBudget;s.headroom=0;}if(typeof hfState==='function')return hfState(s);return s}
const quantNotes={
 Q3_K_M:'Q3_K_M: a heavily compressed mixed-precision format. We budget about 3.9 bits per weight. It saves memory relative to Q4_K_M, with greater risk of quality loss.',
 Q4_0:'Q4_0: roughly 4-bit weights in simple blocks, about 4.5 bits per weight including scales. Usually a little smaller than Q4_K_M. Quality depends on the model and how it was quantized; Q4_0 alone does not imply QAT.',
 Q4_K_M:'Q4_K_M: roughly 4-bit weights with mixed tensor precisions, budgeted at about 4.85 bits per weight. It uses a little more memory than Q4_0 and often preserves quality better for conventional post-training conversions.',
 Q5_K_M:'Q5_K_M: roughly 5-bit weights with mixed tensor precisions, budgeted at about 5.7 bits per weight. More weight memory than Q4_K_M, generally retaining more of the original precision; test whether the quality gain matters for your task.',
 Q6_K:'Q6_K: roughly 6-bit weights, budgeted at about 6.6 bits per weight including block metadata. More weight memory than Q5_K_M, with less compression error in general. Speed depends on hardware and kernels.',
 Q8_0:'Q8_0: roughly 8-bit weights, about 8.5 bits per weight including scales. Uses substantially more weight memory than 4-bit formats and retains more precision. A quality or speed improvement is not guaranteed for your task.',
 FILE:'This GGUF uses a format outside the named presets. Weight memory comes from the selected file size; the format alone does not establish quality or speed.',
 FP16:'FP16: 16-bit floating-point weights. This is the highest weight precision offered here and uses about twice the weight memory of Q8_0. It does not increase context capacity or guarantee better reasoning.'
};
const fmt=n=>n.toFixed(1),colors=['var(--c-weights)','var(--c-kv)','var(--c-runtime)','var(--c-free)'];
function render(){const s=state();if(ids.some(id=>!['quant','memoryType'].includes(id)&&(!$(id).checkValidity()||$(id).value===''))){$('verdict').textContent='Enter valid values in the advanced assumptions to update the estimate.';return}const r=estimate(s);renderMemoryMode(s);$('quantExplanation').textContent=quantNotes[s.quant];
 $('vramO').textContent=s.dedicatedVram+' GiB';$('vramSelected').textContent=s.dedicatedVram+' GiB selected';$('paramsO').textContent=s.params+'B';$('offloadO').textContent=s.offload+'%';$('headroomO').textContent=s.headroom+' GiB';
 $('total').textContent=fmt(r.total);$('required').textContent=fmt(r.required)+' GiB including desired reserve';$('badge').textContent=r.band;const bc=r.band==='Tight'?'tight':['Spill likely','Over budget'].includes(r.band)?'spill':'ok';$('badge').className='pill '+bc;$('forecast').className='panel result band-'+bc;$('miniTotal').textContent=fmt(r.total)+' / '+s.vram+' GiB';$('miniBand').textContent=r.band;$('miniBand').className='pill '+bc;
 const parts=[r.gpuWeights,r.gpuKV,s.overhead,Math.max(0,r.free)],labels=['Model weights','KV cache','Runtime / buffers',s.memoryType==='unified'?'Unused model budget':'Free memory'];const scale=Math.max(s.vram,r.total);
 $('bar').innerHTML=parts.map((v,i)=>`<div title="${labels[i]}: ${fmt(v)} GiB" style="width:${v/scale*100}%;background:${colors[i]}"></div>`).join('');
 $('legend').innerHTML=parts.map((v,i)=>`<span><i style="background:${colors[i]}"></i>${labels[i]} <b>${fmt(v)} GiB</b></span>`).join('');
 $('free').textContent=fmt(r.free)+' GiB';$('ram').textContent=fmt(r.ram)+' GiB';
 $('verdict').textContent=r.band==='Comfortable'?`Room to breathe. This estimate leaves ${fmt(r.free)} GiB free, meeting your ${s.headroom} GiB reserve.`:r.band==='Tight'?`It fits on paper, but leaves only ${fmt(r.free)} GiB free. Reduce context or precision, or use a smaller model to restore your reserve.`:`About ${fmt(-r.free)} GiB over capacity. Reduce model size, context, precision, or GPU offload. Spill can sharply slow responses; loading may fail.`;
 if(r.unified){$('required').textContent=fmt(s.modelBudget)+' GiB chosen model budget';$('ram').textContent='Shared pool';$('verdict').textContent=r.band==='Over budget'?`About ${fmt(-r.free)} GiB above your chosen model budget. This is not a measured hardware limit: reduce model size/context or cautiously increase the budget, leaving room for macOS and applications.`:r.band==='Tight'?`Within your budget, but only ${fmt(r.free)} GiB remains in it. This is the last 10% of the chosen allowance; actual allocations can vary.`:`This estimate leaves ${fmt(r.free)} GiB inside your model budget. Another ${fmt(s.unifiedTotal-s.modelBudget)} GiB is outside that budget for macOS, applications, and safety; it is not measured free memory.`;}
 $('quality').textContent=`${s.params}B describes learned capacity, not an intelligence score. ${s.quant} ${s.quant==='FP16'?'retains the baseline storage precision.':'compresses the learned weights; lower precision can lose detail and reasoning accuracy.'} Compare quality within model families and test your own tasks.`;
 $('memory').textContent=`${(s.context/1024).toFixed(0)}K tokens is room for instructions, conversation, documents, and output together. At the assumed architecture, its full KV cache is ${fmt(r.kv)} GiB before offload. More context lets you keep a longer conversation, provide a larger document or more code, compare sources together, and leave room for a longer answer. It helps when relevant material would otherwise be dropped or summarized. If your exchange already fits comfortably, unused space does not improve answers or increase intelligence.`;
 $('speed').textContent=`${s.offload<100?'Some computation moves to the CPU, often reducing speed.':'Full GPU offload avoids CPU layer work if the allocation fits.'} Longer active prompts take more processing and attention work and can slow responses. Raising the limit from 8K to 16K does not necessarily slow a short exchange: actual token use, cache allocation, and GPU placement matter. A runtime that reserves more memory may offload work to the CPU or spill, causing a sharp slowdown even on a short prompt. Quantization can help speed through lower memory traffic, but kernels and hardware matter. No tokens/sec prediction is implied.`;
 if(r.unified)$('speed').textContent='Apple silicon CPU and GPU share physical memory. Moving layers to the CPU does not free a separate VRAM pool; this estimate counts all model weights and cache once. Metal/MLX GPU acceleration, chip bandwidth, active context, runtime, and memory pressure affect speed. A fit estimate does not predict tokens per second.';
 if(typeof renderHF==='function')renderHF(s);
 if(typeof scheduleRecs==='function')scheduleRecs();
 $('recommendations').hidden=mode!=='gpu';if(mode==='gpu')renderRanges(s);
 try{localStorage.setItem('local-ai-setup',JSON.stringify({s,mode,hfSelection:HF_SELECTION}))}catch{}
}
function normalizeUnifiedBudget(){const total=Number($('unifiedTotal').value);if(!Number.isFinite(total)||total<4)return;$('modelBudget').max=total-2;const b=Number($('modelBudget').value);if(Number.isFinite(b)&&b>total-2)$('modelBudget').value=total-2;}
function renderMemoryMode(s){const u=s.memoryType==='unified';$('unifiedControls').hidden=!u;const ctl=$('vram').closest('.ctl');if(ctl)ctl.hidden=u;for(const id of ['offload','headroom']){const ctl=$(id).closest('.ctl');if(ctl)ctl.hidden=u;}document.querySelectorAll('[data-exp="offload"]').forEach(b=>b.hidden=u);$('memoryUsageLabel').textContent=u?'GiB estimated model memory':'GiB estimated VRAM';$('remainingLabel').textContent=u?'Remaining model budget':'Remaining VRAM';$('offloadedLabel').textContent=u?'CPU / GPU memory':'Offloaded RAM, min*';$('unifiedReserve').textContent=`${fmt(s.unifiedTotal-s.modelBudget)} GiB outside the model budget for macOS, other applications, and safety.`;$('rangesScope').textContent=u?'UNIFIED MODEL BUDGET':'FULL GPU OFFLOAD';$('rangesMemoryNote').textContent=u?'Largest sampled model at each context within the model budget, leaving its final 10% unused. Memory estimates, not quality rankings.':'Largest sampled model at each context, preserving your headroom. Memory limits, not quality rankings.';$('memoryBudgetNote').textContent=u?`${s.unifiedTotal} GiB total unified memory · ${s.modelBudget} GiB chosen model budget. Planning allowance, not dedicated VRAM or measured availability.`:'';}
$('startingBudget').onclick=()=>{$('modelBudget').value=unifiedStartBudget(Number($('unifiedTotal').value));normalizeUnifiedBudget();render()};
function renderRanges(s){let rows=[];for(const q of ['Q4_0','Q4_K_M','Q5_K_M','Q8_0'])for(const context of [4096,8192,32768]){let max=0;for(let p=1;p<=72;p+=.5)if(estimate({...s,weightGiB:undefined,params:p,quant:q,context,offload:100}).band==='Comfortable')max=p;rows.push(`<tr><td>${q}</td><td>${context/1024}K</td><td>${max?`1–${max}B`:'No fit ≥1B'}</td><td>${max?`<button data-p="${max}" data-q="${q}" data-c="${context}">Try ${max}B ↗</button>`:'—'}</td></tr>`)}$('ranges').innerHTML='<table><thead><tr><th>Precision</th><th>Context</th><th>Comfortable range</th><th>Explore</th></tr></thead><tbody>'+rows.join('')+'</tbody></table>'}
ids.forEach(id=>$(id).addEventListener('input',()=>{if(id==='unifiedTotal'){normalizeUnifiedBudget();}if(id==='modelBudget')normalizeUnifiedBudget();if(['params','quant','layers','heads','dim'].includes(id)){selectedModel='';HF_SELECTION=null;if($('quant').value==='FILE')$('quant').value='Q4_K_M';}render()}));
function setMode(m){mode=m;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===m);b.setAttribute('aria-pressed',b.dataset.mode===m)});render()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));

document.querySelectorAll('[data-exp]').forEach(b=>b.onclick=()=>{if(b.dataset.exp==='context'){$('context').value=$('context').value==='131072'?'8192':'131072';b.textContent=$('context').value==='131072'?'Return to 8K context ↙':'8K → 128K context ↗'}if(b.dataset.exp==='quant'){$('quant').value=$('quant').value==='Q8_0'?'Q4_K_M':'Q8_0';b.textContent=$('quant').value==='Q8_0'?'Return to Q4 precision ↙':'Q4 → Q8 precision ↗'}if(b.dataset.exp==='offload'){$('offload').value=$('offload').value==='50'?'100':'50'}render()});
 $('ranges').onclick=e=>{const b=e.target.closest('[data-p]');if(!b)return;HF_SELECTION=null;selectedModel='';$('params').value=b.dataset.p;$('quant').value=b.dataset.q;$('context').value=b.dataset.c;$('offload').value=100;render();$('params').focus()};
 $('reset').onclick=()=>{HF_SELECTION=null;selectedModel='';ids.forEach(id=>$(id).value=defaults[id]);setMode('gpu')};
try{const saved=JSON.parse(localStorage.getItem('local-ai-setup'));if(saved){if(saved.hfSelection&&Number.isFinite(saved.hfSelection.bytes)&&saved.hfSelection.bytes>0)HF_SELECTION=saved.hfSelection;ids.forEach(id=>{if(saved.s[id]!==undefined)$(id).value=id==='vram'?(saved.s.dedicatedVram??saved.s[id]):id==='headroom'?(saved.s.dedicatedHeadroom??saved.s[id]):saved.s[id]})}}catch{}normalizeUnifiedBudget();setMode(mode);
